using System;using System.IO;using System.Linq;using System.Drawing;using System.Drawing.Imaging;using IGM;
class Verify020{static void Check(bool yes,string message){if(!yes)throw new Exception(message);}static void Main(string[]args){string root=Path.Combine(Path.GetTempPath(),"igm52 bundle "+Guid.NewGuid().ToString("N")),bundle=Path.Combine(root,"IGM");Directory.CreateDirectory(bundle);string folder=Data.MigrateBundle(bundle+Path.DirectorySeparatorChar);Project p=new Project();foreach(string s in args)p.Merge(Data.Import(s,""));Check(p.Alliances.Count>0,"Import");Alliance a=p.Alliances[0];foreach(var x in p.Alliances){x.ColorRGB=0;x.Icon="";x.PreviewPng="";}using(var image=new Bitmap(180,180)){using(var g=Graphics.FromImage(image))g.Clear(Color.FromArgb(255,119,51,17));image.SetPixel(1,0,Color.FromArgb(85,120,51,18));image.SetPixel(90,90,Color.Transparent);using(var stream=new MemoryStream()){image.Save(stream,ImageFormat.Png);a.PreviewPng=Convert.ToBase64String(stream.ToArray());}}
string management=Path.Combine(folder,"gestion_sistemas.tsv");File.WriteAllText(management,"#keep favourites\n");string result=Data.Export(p,folder,false);string texture=Path.Combine(folder,"iconos_alianzas",a.ID+".bmp");byte[] first=File.ReadAllBytes(texture);Check(first.Length==54+180*180*4&&BitConverter.ToInt32(first,22)==-180,"BMP header/size");Check(first[54+3]==255&&first[54+7]==85&&first[54+(90*180+90)*4+3]==0,"Alpha preserved");Check(first[54]==17&&first[55]==51&&first[56]==119,"Full colour BGRA");Check(result.Contains("icons: 1"),"Export count");string cat=File.ReadAllText(Path.Combine(folder,"catalogo_observado.jsonl"));Data.Export(p,folder,false);Check(first.SequenceEqual(File.ReadAllBytes(texture))&&cat==File.ReadAllText(Path.Combine(folder,"catalogo_observado.jsonl")),"Idempotence");Check(File.ReadAllText(management)=="#keep favourites\n","Management overwritten");a.PreviewPng="";using(var img=new Bitmap(180,180)){using(var g=Graphics.FromImage(img))g.Clear(Color.Gold);using(var stream=new MemoryStream()){img.Save(stream,ImageFormat.Png);a.PreviewPng=Convert.ToBase64String(stream.ToArray());}}Data.Export(p,folder,false);Check(!first.SequenceEqual(File.ReadAllBytes(texture)),"Icon did not change");Check(Directory.GetFiles(Path.Combine(folder,"copias_companion"),"*.bmp",SearchOption.AllDirectories).Length>0,"Missing backup");File.WriteAllBytes("/tmp/companion52-roundtrip.bmp",first);Console.WriteLine("PASS Companion .NET 4.8 core: actual saves, automatic bundle target with spaces, full colour+alpha BMP, exported icon count, repeat idempotence, changed icon replaced with backup, favourites untouched. Systems="+p.Systems.Count+" alliances="+p.Alliances.Count);}}
